package com.brasa.restaurant.model;import com.brasa.restaurant.enums.Enums.DiaEscala;import jakarta.persistence.*;import java.time.LocalDate;@Entity@Table(name="escalas",uniqueConstraints=@UniqueConstraint(columnNames={"restaurante_id","funcionario_id","semana_referencia"}))public class EscalaSemanal extends BaseEntity{@Column(name="restaurante_id",nullable=false)private String restauranteId;private String funcionarioId;private LocalDate semanaReferencia;@Enumerated(EnumType.STRING)private DiaEscala seg;@Enumerated(EnumType.STRING)private DiaEscala ter;@Enumerated(EnumType.STRING)private DiaEscala qua;@Enumerated(EnumType.STRING)private DiaEscala qui;@Enumerated(EnumType.STRING)private DiaEscala sex;@Enumerated(EnumType.STRING)private DiaEscala sab;@Enumerated(EnumType.STRING)private DiaEscala dom;public String getRestauranteId(){return restauranteId;}public void setRestauranteId(String v){restauranteId=v;}public String getFuncionarioId(){return funcionarioId;}public void setFuncionarioId(String v){funcionarioId=v;}public LocalDate getSemanaReferencia(){return semanaReferencia;}public void setSemanaReferencia(LocalDate v){semanaReferencia=v;}public DiaEscala getSeg(){return seg;}public void setSeg(DiaEscala v){seg=v;}public DiaEscala getTer(){return ter;}public void setTer(DiaEscala v){ter=v;}public DiaEscala getQua(){return qua;}public void setQua(DiaEscala v){qua=v;}public DiaEscala getQui(){return qui;}public void setQui(DiaEscala v){qui=v;}public DiaEscala getSex(){return sex;}public void setSex(DiaEscala v){sex=v;}public DiaEscala getSab(){return sab;}public void setSab(DiaEscala v){sab=v;}public DiaEscala getDom(){return dom;}public void setDom(DiaEscala v){dom=v;}}
